for(const [alias,name] of Object.entries({"accessibility":"wheelchair","chevron-left":"arrow-left","chevron-right":"arrow-right","locate-fixed":"crosshair","lock-keyhole":"lock-key","maximize":"corners-out","move":"arrows-out-cardinal","rotate-3d":"arrows-clockwise"}))phosphorIcons[alias]=phosphorIcons[name];
export const icons=Object.freeze(phosphorIcons);
export const icon=(name,className='')=>{const svg=icons[name];if(!svg)throw Error(`Unknown Phosphor icon: ${name}`);return className?svg.replace('class="phosphor-icon"',`class="phosphor-icon ${className}`):svg;};
